  if (nodeConnection.socketPath) {
    options.socketPath = nodeConnection.socketPath;
  } else {
    options.hostname = urlHost.hostname;
    options.port = urlHost.port;
    setProxy(options, proxy, protocol + '//' + urlHost.hostname + (urlHost.port ? ':' + urlHost.port : '') + options.path);
  }

  var transport;
  var isHttpsRequest = isHttps.test(options.protocol);
  options.agent = isHttpsRequest ? nodeConnection.httpsAgent : nodeConnection.httpAgent;
  if (transportSettings.transport) {
    transport = transportSettings.transport;
  } else if (transportSettings.maxRedirects === 0) {
    transport = isHttpsRequest ? this.httpsModule : this.httpModule;
  } else {
    if (transportSettings.maxRedirects) {
      options.maxRedirects = transportSettings.maxRedirects;
    }
    if (beforeRedirect) {
      options.beforeRedirects.config = beforeRedirect;
    }
    transport = isHttpsRequest ? httpsFollow : httpFollow;
  }

  if (transportSettings.maxBodyLength > -1) {
    options.maxBodyLength = transportSettings.maxBodyLength;
  }

  if (insecureHTTPParser) {
    options.insecureHTTPParser = insecureHTTPParser;
  }

  return {
    options: options,
    transport: transport
  };
};

